/// WGSL world-dimension constants generated by build.rs from `src/world_dims.rs`.
/// Prepended to every shader so the GPU and CPU agree on world size with a
/// single source of truth.
const WORLD_CONSTS_WGSL: &str = include_str!(concat!(env!("OUT_DIR"), "/world_consts.wgsl"));

/// Shared render-shader prelude (Camera uniform + tiny helpers). Prepended
/// after the world consts to raymarch/beam/taa so those three carry one
/// definition instead of a hand-maintained copy each. NOT used by physics/blit.
const COMMON_WGSL: &str = include_str!("../shaders/common.wgsl");

/// The shared in-brick DDA (`resolve_brick`) used by both the RT render path
/// and the accel-probe test, and the RT occlusion prelude that binds the world
/// acceleration structure. Only assembled into the RT shader variant.
const RT_VOXEL_QUERY_WGSL: &str = include_str!("../shaders/rt_voxel_query.wgsl");
const RT_SHADOW_WGSL: &str = include_str!("../shaders/rt_shadow.wgsl");
const RT_GI_WGSL: &str = include_str!("../shaders/rt_gi.wgsl");
const GI_PROBES_WGSL: &str = include_str!("../shaders/gi_probes.wgsl");
/// Probe-update amortization factor: 1/GI_PROBE_UPDATE_DIV of the probes are
/// re-gathered each frame (strided by the camera's gi_round). MUST match the
/// `GI_UPDATE_DIV` override default in gi_probes.wgsl.
const GI_PROBE_UPDATE_DIV: u32 = 8;
/// Probe gather-direction epochs: each probe cycles GI_PROBE_DIR_EPOCHS fixed
/// direction subsets (spherical Fibonacci), one per update round, so a static
/// scene converges to a periodic constant instead of random-walking. The
/// camera's gi_round counts frames mod DIV*EPOCHS: `% DIV` selects the probe
/// slice, `/ DIV` the epoch. MUST match `GI_DIR_EPOCHS` in gi_probes.wgsl.
const GI_PROBE_DIR_EPOCHS: u32 = 8;
const RT_PRIMARY_WGSL: &str = include_str!("../shaders/rt_primary.wgsl");

/// Software dispatchers injected into the non-RT variant so the render body's
/// `shadow_occluded(...)` and `indirect_light(...)` calls resolve to the
/// pre-RT behaviour: occlusion forwards to the DDA `trace_any`, and there is no
/// one-bounce indirect (returns 0, the ambient-only look).
const SHADOW_SW_WGSL: &str = concat!(
    "fn shadow_occluded(o: vec3<f32>, d: vec3<f32>, m: f32) -> bool { return trace_any(o, d, m); }\n",
    "fn indirect_light(p: vec3<f32>, n: vec3<f32>, seed: f32, px: vec2<i32>, t: f32, v: vec3<f32>) -> vec3<f32> { return vec3<f32>(0.0); }\n",
    "fn trace_secondary(o: vec3<f32>, d: vec3<f32>, cap: f32) -> Hit { return trace_no_water(o, d, cap); }\n",
    "fn rt_primary_or_none(origin: vec3<f32>, dir: vec3<f32>, skip_transparent: bool, done: ptr<function, bool>) -> Hit { *done = false; var h: Hit; h.hit = false; h.mat = 0u; h.normal = vec3<f32>(0.0); h.voxel = vec3<i32>(0); h.last_axis = -1; h.t_hit = 0.0; h.tint = vec3<f32>(1.0); return h; }\n",
);

/// Full raymarch shader source: world consts + common prelude + the sprite
/// atlas consts generated from `src/sprites.rs` + the shader body. The ONE
/// assembly point shared by the pipeline, the naga validation test and the
/// GPU test harness, so what is validated/tested is what runs.
///
/// `rt` selects the hardware-ray-tracing variant: it enables `wgpu_ray_query`,
/// binds the world acceleration structure and routes `shadow_occluded` through
/// the RT core. The software variant is byte-identical to the pre-RT shader plus
/// the tiny forwarding dispatcher, so a non-RT GPU renders exactly as before.
pub(crate) fn raymarch_source_variant(rt: bool) -> String {
    if rt {
        format!(
            "enable wgpu_ray_query;\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}",
            WORLD_CONSTS_WGSL,
            COMMON_WGSL,
            crate::sprites::wgsl_consts(),
            RT_VOXEL_QUERY_WGSL,
            RT_SHADOW_WGSL,
            RT_GI_WGSL,
            GI_PROBES_WGSL,
            RT_PRIMARY_WGSL,
            include_str!("../shaders/raymarch.wgsl"),
        )
    } else {
        format!(
            "{}\n{}\n{}\n{}\n{}",
            WORLD_CONSTS_WGSL,
            COMMON_WGSL,
            crate::sprites::wgsl_consts(),
            include_str!("../shaders/raymarch.wgsl"),
            SHADOW_SW_WGSL,
        )
    }
}

/// Software (non-RT) raymarch source. Kept as the name the existing pipeline,
/// validation test and GPU harness call.
pub(crate) fn raymarch_source() -> String {
    raymarch_source_variant(false)
}

/// Pack a Vec<u8> into Vec<u32> for storage-buffer upload (WGSL storage
/// buffers can't directly index u8 arrays; reading byte b of word w via
/// `(packed[w] >> ((b & 3) * 8)) & 0xFF` is the canonical pattern).
fn pack_u8_to_u32(src: &[u8]) -> Vec<u32> {
    let n_words = (src.len() + 3) / 4;
    let mut out = vec![0u32; n_words];
    for (i, &b) in src.iter().enumerate() {
        let w = i >> 2;
        let bit = (i & 3) * 8;
        out[w] |= (b as u32) << bit;
    }
    out
}

/// Coalesce a SORTED, DEDUPED slice of element indices into contiguous runs and
/// invoke `f(start, end_inclusive)` once per run. Turns thousands of tiny DMAs
/// into a handful of multi-KB writes.
fn upload_spans(sorted: &[u32], mut f: impl FnMut(u32, u32)) {
    let mut i = 0usize;
    while i < sorted.len() {
        let start = sorted[i];
        let mut end = start;
        let mut j = i + 1;
        while j < sorted.len() && sorted[j] == end + 1 {
            end = sorted[j];
            j += 1;
        }
        f(start, end);
        i = j;
    }
}

/// Upload the given packed-u32 word indices (sorted, deduped) of a byte table
/// (1 byte per element, packed 4 per word) by re-packing each contiguous word
/// run from `bytes` and writing it at the matching word offset.
fn upload_packed_word_spans(
    words: &[u32],
    bytes: &[u8],
    queue: &wgpu::Queue,
    buf: &wgpu::Buffer,
) {
    upload_spans(words, |w_start, w_end| {
        let b0 = (w_start as usize) * 4;
        let b1 = (((w_end as usize) + 1) * 4).min(bytes.len());
        let packed = pack_u8_to_u32(&bytes[b0..b1]);
        queue.write_buffer(buf, w_start as u64 * 4, bytemuck::cast_slice(&packed));
    });
}

/// Project element indices `src` to their packed-u32 word indices (deduped via
/// `scratch`) and re-pack + upload only those words of the byte `table`. Shared
/// by the brick-uniform and tile-uniform incremental uploads.
fn upload_words_for(
    scratch: &mut Vec<u32>, src: &[u32], table: &[u8], queue: &wgpu::Queue, buf: &wgpu::Buffer,
) {
    scratch.clear();
    for &x in src {
        let w = x >> 2;
        if scratch.last() != Some(&w) { scratch.push(w); }
    }
    upload_packed_word_spans(scratch, table, queue, buf);
}

/// Project a set of tile indices up to their parent chunks (via `scratch`, which
/// is sorted+deduped) and DMA the touched chunk_mask runs. Does NOT refresh L4 —
/// the caller decides that.
fn upload_chunks_for_tiles(
    scratch: &mut Vec<u32>, tiles: &[u32], chunk_mask: &[u64], queue: &wgpu::Queue, buf: &wgpu::Buffer,
) {
    scratch.clear();
    for &t in tiles {
        let tx = t % WORLD_TILES_X;
        let ty = (t / WORLD_TILES_X) % WORLD_TILES_Y;
        let tz = t / (WORLD_TILES_X * WORLD_TILES_Y);
        scratch.push(chunk_idx(tx / 4, ty / 4, tz / 4));
    }
    scratch.sort_unstable();
    scratch.dedup();
    upload_spans(scratch, |s, e| {
        let slice = &chunk_mask[s as usize..=e as usize];
        queue.write_buffer(buf, s as u64 * 8, bytemuck::cast_slice(slice));
    });
}

